/* StewardMD — build kb/dist/kb.rag.js  (RAG grounding data for the browser)
 *
 * Bundles the two knowledge sources the browser does NOT already have loaded, so
 * the client-side RAG layer (kb/ai/interface.mjs) can resolve treatment precedence
 * (ICMR ▸ guideline ▸ Harrison) and hospital overlays without shipping the 12 MB
 * chunk index:
 *   window.KB_RAG = {
 *     treatments: { <diseaseId>: <treatment> },          // keyed by diseaseId (not filename)
 *     policies:   { <hospitalId>: { hospitalId, diseases:{<id>:{entry,hospital}} } }  // filled overlays only
 *   }
 * Harrison KB chunks are NOT bundled here — the browser derives them from the
 * already-loaded window.KB_ENRICHMENT (+ KB_CORE) at runtime (offline, no download).
 *
 * Lazy-loaded by the app ONLY when the smd_ai flag is on. USAGE: node kb/tools/build-kb-rag-bundle.mjs [version]
 */
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..", "..");
const TX = join(ROOT, "kb", "treatments");
const POL = join(ROOT, "kb", "policies");
const OUT = join(ROOT, "kb", "dist", "kb.rag.js");
const version = process.argv[2] || "1";

const treatments = {};
for (const f of readdirSync(TX).filter((x) => x.endsWith(".json"))) {
  const t = JSON.parse(readFileSync(join(TX, f), "utf8"));
  if (t && t.diseaseId) treatments[t.diseaseId] = t;   // key by diseaseId (interface.resolveTreatment expects this)
}

// hospital overlays — keep ONLY diseases that actually have a filled entry (drops empty scaffolds; slims GIMSR)
const policies = {};
if (existsSync(POL)) {
  for (const f of readdirSync(POL).filter((x) => x.endsWith(".json"))) {
    const p = JSON.parse(readFileSync(join(POL, f), "utf8"));
    const id = p.hospitalId || f.replace(/\.json$/, "");
    const filled = {};
    for (const dz in (p.diseases || {})) { const e = p.diseases[dz]; if (e && e.entry) filled[dz] = e; }
    if (Object.keys(filled).length) policies[id] = { hospitalId: id, diseases: filled };
  }
}

const payload = { version, treatments, policies };
writeFileSync(OUT, "/* GENERATED by kb/tools/build-kb-rag-bundle.mjs — RAG grounding data (treatments + hospital overlays). Lazy-loaded when smd_ai is ON. */\nwindow.KB_RAG = " + JSON.stringify(payload) + ";\n");
const overlays = Object.keys(policies).map((h) => h + ":" + Object.keys(policies[h].diseases).length).join(", ");
console.log(`treatments=${Object.keys(treatments).length}  overlays={${overlays}}  version=${version}  -> ${OUT} (${Math.round(readFileSync(OUT).length / 1024)} KB)`);
